const j = $input.first().json;
const name = String(j['Nome completo'] || j.Nome || '').trim();
const email = String(j['E-mail'] || j.Email || '').trim().toLowerCase();
const phone = String(j.Telefone || '').replace(/\D/g,'');
const password = String(j.Senha || '');
if (name.length < 3) throw new Error('Nome curto.');
if (!email.includes('@')) throw new Error('E-mail inválido.');
if (phone.length < 10) throw new Error('Telefone incompleto.');
if (password.length < 8) throw new Error('Senha com no mínimo 8 caracteres.');
function hash(pw, salt){ return crypto.pbkdf2Sync(pw, salt, 120000, 32, 'sha256').toString('hex'); }
if (s.users[email]) {
  const u = s.users[email];
  if (u.passwordHash !== hash(password, u.salt)) throw new Error('Conta já existe e a senha não confere.');
} else {
  const salt = crypto.randomBytes(16).toString('hex');
  s.users[email] = { name, email, phone, salt, passwordHash: hash(password, salt), createdAt: new Date().toISOString() };
}
const HOUSE = [3,7,11,16,22,28,32,35];
let open = s.draws.find(d => d.status === 'open');
