}
const mine = s.tickets.filter(t => t.email===email && t.drawId===drawId);
const total = mine.reduce((a,t)=>a+t.priceCents,0);
function emv(id, value){ return id + String(value.length).padStart(2,'0') + value; }
function crc16(payload){ let crc=0xffff; for (let i=0;i<payload.length;i++){ crc ^= payload.charCodeAt(i)<<8; for(let b=0;b<8;b++) crc = crc&0x8000?(crc<<1)^0x1021:crc<<1, crc&=0xffff;} return crc.toString(16).toUpperCase().padStart(4,'0'); }
const txid = 'SIM'+Date.now().toString(36).toUpperCase();
mine.forEach(t => { t.status='awaiting_pix'; t.pixTxid=txid; });
const amount=(total/100).toFixed(2);
const gui=emv('00','BR.GOV.BCB.PIX')+emv('01','simulacao-educacional@local');
const add=emv('05', txid.slice(0,25));
const base=emv('00','01')+emv('01','12')+emv('26',gui)+emv('52','0000')+emv('53','986')+emv('54',amount)+emv('58','BR')+emv('59','36 BICHOS SIM')+emv('60','PORTO ALEGRE')+emv('62',add)+'6304';
const payload=base+crc16(base);
const nomes = mine.map(t => {
  const a = ANIMALS.find(x=>x.n===t.animalNumber);
  return `${String(t.animalNumber).padStart(2,'0')} ${a?a.name:''}`;
}).join(' · ');
return [{ json: { ...prev, msgs: msgs.join(' '), nomes, total, totalFmt: (total/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), payload, txid, ganho: (500*18/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}) } }];

